  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "High rates of maternal mortality and morbidity remain significant health issues in low- and middle-income countries. Despite this, few researchers have investigated the underlying factors of severe maternal complications in sub-Saharan Africa.",
      "reason": "Background explicitly states the current state of knowledge (high rates, few researchers investigating underlying factors), identifying an important uncertainty that motivates the review."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Therefore, the objective of this systematic review was to determine the socioeconomic, demographic, and obstetric predictors of severe maternal complications in this region.",
      "reason": "The manuscript explains the need and purpose of the review by stating the objective to determine predictors in a context where few researchers have addressed the issue, indicating the importance of conducting the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit discussion was found about existing similar systematic reviews, nor citation or justification of how this review updates or differs from prior reviews in the provided evidence."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "Therefore, the objective of this systematic review was to determine the socioeconomic, demographic, and obstetric predictors of severe maternal complications in this region.",
      "reason": "The review addresses determinants/predictors rather than intervention effects; thus describing an intervention's mechanism is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "Therefore, the objective of this systematic review was to determine the socioeconomic, demographic, and obstetric predictors of severe maternal complications in this region.",
      "reason": "The review does not evaluate a complex intervention or delivery context, so inclusion of a logic model is not applicable."
    }
  ],
  "confidence": "75"
