{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The aim of this systematic review was to identify socio-economic, demographic and obstetric factors predictive of maternal near-miss (MNM)in women aged 15-49 years in Africa.",
      "reason": "The manuscript explicitly states the review aim/objective, describing the population (women aged 15–49 in Africa) and the factors of interest (socio-economic, demographic and obstetric predictors of MNM)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_10",
      "quote": "This review used the PECO (Population, Exposure, Comparison and Outcomes) approach to research, with the following parameters: Population: Pregnant, labouring, or postpartum women up to 42 days after delivery in Africa. Exposure: factors predictive of MNM, such as factors related to the prenatal period (presence of a prenatal visit and frequency of prenatal visit), sociodemographic characteristics and delay in access to care. Comparison: reference group reported for each predictive factor in each respective study. Outcome: occurrence of MNM in women.",
      "reason": "The review addresses predictive/observational questions using a PECO framework rather than intervention effects; therefore PICO-stated planned comparisons for interventions are not applicable."
    }
  ],
  "confidence": "95"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Articles included in this systematic review had to meet the following criteria: they had to present the results of research studies carried out on women who had experienced maternal nearmiss in Africa, examine the socio-economic, demographic and obstetric factors influencing the occurrence of these accidents, and be published between January 2000 and December 15, 2022. There were no language restrictions, and no prior restrictions on study design (qualitative, quantitative, or mixed methods). Studies without abstracts or for which the full text was not available were excluded. No studies were excluded on the basis of quality assessment. This review used the PECO (Population, Exposure, Comparison and Outcomes) approach to research, with the following parameters: Population: Pregnant, labouring, or postpartum women up to 42 days after delivery in Africa. Exposure: factors predictive of MNM, such as factors related to the prenatal period (presence of a prenatal visit and frequency of prenatal visit), sociodemographic characteristics and delay in access to care. Comparison: reference group reported for each predictive factor in each respective study. Outcome: occurrence of MNM in women.",
      "reason": "The eligibility criteria explicitly define population, exposures, comparisons, outcomes (PECO), eligible study designs (no restrictions), geographic setting (Africa), publication date range, and exclusions for unavailable full text."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "…and be published between January 2000 and December 15, 2022. There were no language restrictions, and no prior restrictions on study design (qualitative, quantitative, or mixed methods). Studies without abstracts or for which the full text was not available were excluded.",
      "reason": "The review specifies dissemination years and language restrictions (none) and notes exclusion of studies without full text, but it does not state other report-characteristic criteria such as publication or report status (e.g., unpublished/grey literature inclusion/exclusion) or explicit rationale for those report-status choices."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_18",
      "quote": "We assessed the eligibility of 255 full-text articles after excluding 932 duplicates and 1814 articles not relevant with our research, notably the lack of analysis of the association between the determinants and maternal near miss and studies outside the African continent. We had 230 articles were excluded in the final stage of eligibility assessment, and the remaining 25 articles were included in this study. The reasons for the exclusion of most studies were: irrelevant results, studies that did not report separate results for maternal mortality and maternal near miss.",
      "reason": "The authors explicitly distinguish exclusions due to lack of analysis of associations and due to studies not reporting separate results for maternal mortality versus maternal near miss, differentiating outcome-not-measured from outcome-not-reported reasons."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "This review used the PECO (Population, Exposure, Comparison and Outcomes) approach to research, with the following parameters: Population: Pregnant, labouring, or postpartum women up to 42 days after delivery in Africa. Exposure: factors predictive of MNM, such as factors related to the prenatal period (presence of a prenatal visit and frequency of prenatal visit), sociodemographic characteristics and delay in access to care. Comparison: reference group reported for each predictive factor in each respective study. Outcome: occurrence of MNM in women.",
      "reason": "The review defines comparisons in PECO and indicates that reference groups were those reported in each study, but it does not explicitly describe the groups used in each synthesis or clearly link synthesized groups to the comparisons defined in the review objectives (no explicit synthesis-group definitions)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although some eligibility restrictions are stated (e.g., date range, exclusion if full text unavailable), the authors do not provide rationales explaining why these notable restrictions (such as the chosen publication date range or exclusion of studies without full text) were applied."
    }
  ],
  "confidence": "80"
}

